<?php
declare(strict_types=1);

final class FitMcpController {
  public static function handle(PDO $pdo, array $cfg): bool {
    $path=fit_request_path();
    if (!in_array($path,['/.well-known/oauth-protected-resource/fit-mcp','/.well-known/oauth-authorization-server','/fit-mcp/authorize','/fit-mcp/token','/fit-mcp/revoke','/fit-mcp/mcp'],true)) return false;
    if (empty($cfg['fit_mcp_enabled']) || empty($cfg['fit_mcp_base_url'])) { http_response_code(404); echo 'Not found'; return true; }
    if ($path==='/.well-known/oauth-protected-resource/fit-mcp') { self::json(['resource'=>$cfg['fit_mcp_base_url'].'/fit-mcp/mcp','authorization_servers'=>[$cfg['fit_mcp_base_url']],'scopes_supported'=>['fit.read','fit.write']]); return true; }
    if ($path==='/.well-known/oauth-authorization-server') { self::json(['issuer'=>$cfg['fit_mcp_base_url'],'authorization_endpoint'=>$cfg['fit_mcp_base_url'].'/fit-mcp/authorize','token_endpoint'=>$cfg['fit_mcp_base_url'].'/fit-mcp/token','revocation_endpoint'=>$cfg['fit_mcp_base_url'].'/fit-mcp/revoke','response_types_supported'=>['code'],'grant_types_supported'=>['authorization_code'],'code_challenge_methods_supported'=>['S256'],'scopes_supported'=>['fit.read','fit.write']]); return true; }
    if ($path==='/fit-mcp/authorize') { self::authorize($pdo,$cfg); return true; }
    if ($path==='/fit-mcp/token') { self::token($pdo,$cfg); return true; }
    if ($path==='/fit-mcp/revoke') { self::revoke($pdo); return true; }
    self::mcp($pdo); return true;
  }
  private static function revoke(PDO $pdo): void { if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);return;}$token=(string)($_POST['token']??'');if($token!=='')$pdo->prepare('UPDATE fit_oauth_access_token SET revoked_at=NOW() WHERE token_hash=?')->execute([hash('sha256',$token)]);http_response_code(200);header('Cache-Control: no-store'); }
  private static function authorize(PDO $pdo,array $cfg): void {
    require_once __DIR__.'/../csrf.php'; $client=self::client($cfg,(string)($_REQUEST['client_id']??'')); $redirect=(string)($_REQUEST['redirect_uri']??'');
    if(!$client || !in_array($redirect,$client['redirect_uris']??[],true) || ($_REQUEST['response_type']??'')!=='code' || !preg_match('/^[A-Za-z0-9._~-]{43,128}$/',(string)($_REQUEST['code_challenge']??''))) { http_response_code(400); echo 'Invalid OAuth authorization request'; return; }
    $user=current_user($pdo); if(!$user){http_response_code(401);echo 'Connectez-vous au portail, puis relancez l’autorisation MCP.';return;}
    $scopes=self::scopes((string)($_REQUEST['scope']??'fit.read')); if($scopes===''){http_response_code(400);echo 'Invalid scope';return;}
    if($_SERVER['REQUEST_METHOD']==='POST') { csrf_check($pdo,(int)$user['id'],(string)($_POST['csrf']??'')); if(($_POST['approve']??'')!=='1'){self::redirectError($redirect,(string)$_REQUEST['state']);return;} $code=rtrim(strtr(base64_encode(random_bytes(32)),'+/','-_'),'='); $pdo->prepare('INSERT INTO fit_oauth_authorization_code(code_hash,user_id,client_id,redirect_uri,scopes,code_challenge,expires_at) VALUES(?,?,?,?,?,?,DATE_ADD(NOW(),INTERVAL 5 MINUTE))')->execute([hash('sha256',$code),(int)$user['id'],$client['client_id'],$redirect,$scopes,(string)$_REQUEST['code_challenge']]); header('Location: '.$redirect.(str_contains($redirect,'?')?'&':'?').'code='.rawurlencode($code).'&state='.rawurlencode((string)$_REQUEST['state']));exit; }
    $csrf=csrf_token($pdo,(int)$user['id']); header('Content-Type: text/html; charset=utf-8'); echo '<!doctype html><meta charset="utf-8"><title>Autoriser Fit</title><form method="post"><input type="hidden" name="csrf" value="'.htmlspecialchars($csrf,ENT_QUOTES,'UTF-8').'">'; foreach(['client_id','redirect_uri','response_type','code_challenge','state','scope'] as $k) echo '<input type="hidden" name="'.$k.'" value="'.htmlspecialchars((string)($_GET[$k]??''),ENT_QUOTES,'UTF-8').'">'; echo '<p>Autoriser <strong>'.htmlspecialchars($client['client_id'],ENT_QUOTES,'UTF-8').'</strong> avec le périmètre <strong>'.htmlspecialchars($scopes,ENT_QUOTES,'UTF-8').'</strong> ?</p><button name="approve" value="1">Autoriser</button><button name="approve" value="0">Refuser</button></form>';
  }
  private static function token(PDO $pdo,array $cfg): void { if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);return;} $client=self::client($cfg,(string)($_POST['client_id']??'')); $code=(string)($_POST['code']??'');$redirect=(string)($_POST['redirect_uri']??'');$verifier=(string)($_POST['code_verifier']??'');if(!$client||!in_array($redirect,$client['redirect_uris']??[],true)||!preg_match('/^[A-Za-z0-9._~-]{43,128}$/',$verifier)){self::oauthError();return;}$st=$pdo->prepare('SELECT * FROM fit_oauth_authorization_code WHERE code_hash=? AND expires_at>NOW() AND consumed_at IS NULL FOR UPDATE');$pdo->beginTransaction();try{$st->execute([hash('sha256',$code)]);$row=$st->fetch();if(!$row||$row['client_id']!==$client['client_id']||$row['redirect_uri']!==$redirect||!hash_equals($row['code_challenge'],rtrim(strtr(base64_encode(hash('sha256',$verifier,true)),'+/','-_'),'='))){$pdo->rollBack();self::oauthError();return;}$token=rtrim(strtr(base64_encode(random_bytes(32)),'+/','-_'),'=');$pdo->prepare('UPDATE fit_oauth_authorization_code SET consumed_at=NOW() WHERE id=?')->execute([$row['id']]);$pdo->prepare('INSERT INTO fit_oauth_access_token(token_hash,user_id,client_id,scopes,expires_at) VALUES(?,?,?,?,DATE_ADD(NOW(),INTERVAL 1 HOUR))')->execute([hash('sha256',$token),$row['user_id'],$row['client_id'],$row['scopes']]);$pdo->commit();self::json(['access_token'=>$token,'token_type'=>'Bearer','expires_in'=>3600,'scope'=>$row['scopes']]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;} }
  private static function mcp(PDO $pdo): void { $auth=(string)($_SERVER['HTTP_AUTHORIZATION']??'');if(!preg_match('/^Bearer ([A-Za-z0-9_-]{30,})$/',$auth,$m)){http_response_code(401);header('WWW-Authenticate: Bearer');return;}$st=$pdo->prepare('SELECT * FROM fit_oauth_access_token WHERE token_hash=? AND expires_at>NOW() AND revoked_at IS NULL');$st->execute([hash('sha256',$m[1])]);$t=$st->fetch();if(!$t||!str_contains(' '.$t['scopes'].' ',' fit.read ')){http_response_code(403);return;}$body=json_decode((string)file_get_contents('php://input'),true);$method=$body['method']??'';$id=$body['id']??null;$tools=[['name'=>'fit_get_context','description'=>'Contexte Fit autorisé','inputSchema'=>['type'=>'object','properties'=>[]]],['name'=>'fit_get_configuration','description'=>'Règles versionnées','inputSchema'=>['type'=>'object','properties'=>[]]],['name'=>'fit_save_profile','description'=>'Enregistre un profil après confirmation explicite','inputSchema'=>['type'=>'object','properties'=>['profile_data'=>['type'=>'object'],'timezone'=>['type'=>'string'],'confirmed'=>['type'=>'boolean']], 'required'=>['profile_data','confirmed']]],['name'=>'fit_save_rule_block','description'=>'Versionne un bloc de règles après confirmation explicite','inputSchema'=>['type'=>'object','properties'=>['code'=>['type'=>'string'],'configuration_data'=>['type'=>'object'],'confirmed'=>['type'=>'boolean']], 'required'=>['code','configuration_data','confirmed']]],['name'=>'fit_open_or_resume_draft','description'=>'Ouvre ou reprend une séance après confirmation','inputSchema'=>['type'=>'object','properties'=>['confirmed'=>['type'=>'boolean']], 'required'=>['confirmed']]],['name'=>'fit_checkpoint_draft','description'=>'Enregistre les séries d’un brouillon après confirmation','inputSchema'=>['type'=>'object','properties'=>['draft_id'=>['type'=>'integer'],'payload'=>['type'=>'object'],'confirmed'=>['type'=>'boolean']], 'required'=>['draft_id','payload','confirmed']]],['name'=>'fit_close_draft','description'=>'Clôture une séance après confirmation','inputSchema'=>['type'=>'object','properties'=>['draft_id'=>['type'=>'integer'],'payload'=>['type'=>'object'],'confirmed'=>['type'=>'boolean']], 'required'=>['draft_id','payload','confirmed']]]];if($method==='tools/list')self::json(['jsonrpc'=>'2.0','id'=>$id,'result'=>['tools'=>$tools]]);if($method==='tools/call'){ $service=fit_service($pdo);$name=$body['params']['name']??'';$args=$body['params']['arguments']??[];$data=null;if($name==='fit_get_context')$data=$service->getSessionContext((int)$t['user_id']);elseif($name==='fit_get_configuration')$data=$service->getConfigurationStatus((int)$t['user_id']);elseif(in_array($name,['fit_save_profile','fit_save_rule_block','fit_open_or_resume_draft','fit_checkpoint_draft','fit_close_draft'],true)){if(!str_contains(' '.$t['scopes'].' ',' fit.write ')||($args['confirmed']??false)!==true){self::json(['jsonrpc'=>'2.0','id'=>$id,'error'=>['code'=>-32003,'message'=>'fit.write scope and confirmed=true required']]);}if($name==='fit_save_profile')$data=$service->saveProfile((int)$t['user_id'],is_array($args['profile_data']??null)?$args['profile_data']:[],isset($args['timezone'])?(string)$args['timezone']:null);elseif($name==='fit_save_rule_block')$data=$service->saveRuleBlock((int)$t['user_id'],(string)($args['code']??''),is_array($args['configuration_data']??null)?$args['configuration_data']:[]);elseif($name==='fit_open_or_resume_draft')$data=$service->openOrResumeDraft((int)$t['user_id']);elseif($name==='fit_checkpoint_draft')$data=$service->checkpointDraft((int)$t['user_id'],(int)($args['draft_id']??0),is_array($args['payload']??null)?$args['payload']:[]);else $data=$service->closeDraft((int)$t['user_id'],(int)($args['draft_id']??0),is_array($args['payload']??null)?$args['payload']:[]);}else self::json(['jsonrpc'=>'2.0','id'=>$id,'error'=>['code'=>-32602,'message'=>'Unknown tool']]);self::json(['jsonrpc'=>'2.0','id'=>$id,'result'=>['content'=>[['type'=>'text','text'=>json_encode($data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]]]]);}self::json(['jsonrpc'=>'2.0','id'=>$id,'error'=>['code'=>-32601,'message'=>'Method not found']]); }
  private static function scopes(string $requested):string{$s=array_unique(array_filter(explode(' ',trim($requested))));sort($s);return $s && !array_diff($s,['fit.read','fit.write']) && in_array('fit.read',$s,true)?implode(' ',$s):'';} private static function client(array $cfg,string $id):?array{$all=json_decode((string)($cfg['fit_oauth_clients']??''),true);if(!is_array($all))return null;foreach($all as $c)if(is_array($c)&&($c['client_id']??'')===$id)return $c;return null;} private static function oauthError():void{self::json(['error'=>'invalid_grant'],400);} private static function redirectError(string $u,string $s):void{header('Location: '.$u.(str_contains($u,'?')?'&':'?').'error=access_denied&state='.rawurlencode($s));exit;} private static function json(array $v,int $s=200):never{http_response_code($s);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');echo json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
}
